// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: playfairFamily } = loadPlayfair();



export type HouseRevealProps = Record<string, any>;

const HouseReveal: React.FC<HouseRevealProps> = ({
  backgroundColor = "#F7F9FC",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "Ta-Da!",
  confettiCount = 150,
  confettiColors = ["#FFC700", "#FF477E", "#00E5FF", "#7000FF", "#00CC66"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic particles for the confetti explosion
  const particles = useMemo(() => {
    return Array.from({ length: confettiCount }).map((_, i) => {
      // Use remotion's seeded random to ensure anti-flicker determinism
      const angle = random(`angle-${i}`) * Math.PI * 2;
      // Explode outwards, covering a good portion of the screen
      const maxDist = (Math.min(width, height) * 0.8) + (random(`dist-${i}`) * 400);
      const size = random(`size-${i}`) * 25 + 10;
      const colorIndex = Math.floor(random(`color-${i}`) * confettiColors.length);
      const color = confettiColors[colorIndex];
      const rotSpeed = (random(`rotSpeed-${i}`) - 0.5) * 30;
      // Some particles are squares, some are circles, some are thin rectangles
      const shapeType = random(`shape-${i}`);
      const delay = random(`delay-${i}`) * 10;

      return { angle, maxDist, size, color, rotSpeed, shapeType, delay };
    });
  }, [confettiCount, confettiColors, width, height]);

  // House Animation Logic
  const houseRevealFrame = 15; // Wait for explosion to clear slightly
  const houseScale = spring({
    fps,
    frame: frame - houseRevealFrame,
    config: { damping: 12, stiffness: 90, mass: 1 },
  });
  
  const houseRotation = interpolate(
    spring({
      fps,
      frame: frame - houseRevealFrame,
      config: { damping: 15, stiffness: 80 },
    }),
    [0, 1],
    [-10, 0] // Slight twist as it scales in
  );

  const houseOpacity = interpolate(
    frame - houseRevealFrame,
    [0, 10],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Text Animation Logic
  const textRevealFrame = 35;
  const textTranslateY = interpolate(
    spring({
      fps,
      frame: frame - textRevealFrame,
      config: { damping: 14, stiffness: 100 },
    }),
    [0, 1],
    [50, 0]
  );
  
  const textOpacity = interpolate(
    frame - textRevealFrame,
    [0, 15],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* HOUSE LAYER (Behind some confetti, but above the background) */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            width: width * 0.6, // Smaller house
            transform: `scale(${houseScale}) rotate(${houseRotation}deg)`,
            opacity: houseOpacity,
            display: "flex",
            flexDirection: "column",
            position: "relative",
            transition: "none",
            marginTop: -height * 0.15, // Shift up slightly to make room for larger text
          }}
        >
          {/* ViewBox adjusted to crop tightly around the house elements */}
          <svg viewBox="30 100 240 260" style={{ width: "100%", height: "auto", display: "block" }}>
            {/* House Body */}
            <rect x="60" y="210" width="180" height="140" fill="#FFFFFF" stroke="#1A1A1A" strokeWidth="8" rx="8" />
            
            {/* Roof */}
            <path d="M 40 210 L 150 110 L 260 210 Z" fill={confettiColors[1] || "#FF477E"} stroke="#1A1A1A" strokeWidth="8" strokeLinejoin="round" />
            
            {/* Door */}
            <rect x="125" y="270" width="50" height="80" fill={confettiColors[4] || "#00CC66"} stroke="#1A1A1A" strokeWidth="8" rx="4" />
            
            {/* Door knob */}
            <circle cx="160" cy="315" r="4" fill="#1A1A1A" />
            
            {/* Window */}
            <rect x="80" y="235" width="30" height="30" fill={confettiColors[2] || "#00E5FF"} stroke="#1A1A1A" strokeWidth="8" rx="4" />
            <rect x="190" y="235" width="30" height="30" fill={confettiColors[2] || "#00E5FF"} stroke="#1A1A1A" strokeWidth="8" rx="4" />
          </svg>
        </div>

        {/* TEXT LAYER */}
        <div
          style={{
            position: "absolute",
            bottom: height * 0.15, // Safe zone aware
            width: "90%",
            textAlign: "center",
            transform: `translateY(${textTranslateY}px)`,
            opacity: textOpacity,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 16,
            transition: "none",
          }}
        >
          <h1
            style={{
              margin: 0,
              fontFamily: playfairFamily,
              fontSize: 110, // Larger text
              fontWeight: 800,
              color: "#1A1A1A",
              lineHeight: 1.1,
              textShadow: "0 4px 12px rgba(255,255,255,0.8)",
              transition: "none",
            }}
          >
            {title}
          </h1>
        </div>
      </AbsoluteFill>

      {/* CONFETTI LAYER (Explodes from center) */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
          pointerEvents: "none",
        }}
      >
        {particles.map((p, i) => {
          const pFrame = frame - p.delay;
          
          // Explosion burst (fast out, slows down)
          const burstProgress = spring({
            fps,
            frame: pFrame,
            config: { damping: 12, stiffness: 80, mass: 1 },
          });

          // Gravity effect (kicks in after initial burst)
          const gravity = Math.max(0, pFrame - 10) * (Math.max(0, pFrame - 10) * 0.5);

          const x = Math.cos(p.angle) * p.maxDist * burstProgress;
          const y = (Math.sin(p.angle) * p.maxDist * burstProgress) + gravity;
          const rotation = p.rotSpeed * pFrame;

          // Fade out near the end of the duration
          const opacity = interpolate(
            frame,
            [durationInFrames - 30, durationInFrames - 5],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Render nothing if particle hasn't appeared yet or has faded out entirely
          if (pFrame < 0 || opacity <= 0) return null;

          const isCircle = p.shapeType > 0.6;
          const isLine = p.shapeType < 0.2;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                width: isLine ? p.size * 1.5 : p.size,
                height: isLine ? p.size * 0.3 : p.size,
                backgroundColor: p.color,
                borderRadius: isCircle ? "50%" : isLine ? "4px" : "20%",
                transform: `translate(${x}px, ${y}px) rotate(${rotation}deg)`,
                opacity,
                transition: "none",
                // Initial scale pop for the confetti
                scale: interpolate(pFrame, [0, 5], [0, 1], { extrapolateRight: "clamp" }),
              }}
            />
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default HouseReveal;